import{z as d,x as A,o as t,c as B,q as s,j as n,D as e,d as o,s as l,S as i,b as E}from"./chunks/framework.C8m1ZpeB.js";const C=JSON.parse('{"title":"安全启动链","description":"","frontmatter":{"title":"安全启动链","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/secure-boot-chain.md","filePath":"cs/secure-boot-chain.md","lastUpdated":1791063341000}'),p={name:"cs/secure-boot-chain.md"};function b(m,a,D,c,u,h){const r=A("Mermaid");return t(),B("div",null,[a[2]||(a[2]=s('<h1 id="安全启动链" tabindex="-1">安全启动链 <a class="header-anchor" href="#安全启动链" aria-label="Permalink to &quot;安全启动链&quot;">​</a></h1><div class="epigraph"><p>安全启动从不可变的 ROM 锚开始，每一级只启动被上一签过的下一镜像。链断在固件更新、密钥管理或「为了方便关掉验证」。</p><footer>—— 据 UEFI Secure Boot；NIST SP 800-147；对照 Anderson 对启动完整性</footer></div><p>上一课<a href="/cs/remote-attestation">远程证明</a>把本机度量报给远端；它预设<strong>本机启动路径的度量先要诚实</strong>。本课讲这条链：ROM→固件→引导器→内核，不写绕过步骤。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>没有这条链，rootkit 可以先于内核加载：引导扇区或固件里的植入对操作系统不可见——它就是「操作系统脚下的地面」。UEFI 安全启动的答案是密钥层级：PK（平台所有者）签 KEK（密钥交换钥），KEK 维护 db（可执行镜像的签名库）与 dbx（吊销库），固件只启动 db 内有签名的镜像。缺口是运营面的密钥管理：固件更新怎么签、自建模块与双启动系统怎么进白名单、dbx 吊销怎么推到存量机器。<span class="marginnote">这套密钥层级翻译成大白话：PK 是「老板的公章」，只用来给 KEK 授权；KEK 是「部门的章」，负责往白名单 db 里添签名、往黑名单 dbx 里添吊销记录；固件本身只认名单不看人——镜像上有 db 里的章且不在 dbx，才放行。</span></p><h3 id="measured-boot" tabindex="-1">measured boot <a class="header-anchor" href="#measured-boot" aria-label="Permalink to &quot;measured boot&quot;">​</a></h3><p>区分两件事：安全启动是<strong>拒绝</strong>——未签镜像根本不执行；度量启动是<strong>记录</strong>——每级镜像的哈希链式写进 TPM 的 PCR，供远程证明读取。一个防执行，一个供审计，可并存且应当并存。</p><p><span class="marginnote">SP 800-147。禁止绕过教程。固件安全下一课把更新与植入当主题。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>方法是把签名链画全：ROM 锚不可变，固件验下一级固件，引导器验内核，每级只启动「被上一级签过」的镜像。运营要对照砖机风险：验证过严而更新流程出错，机器会拒绝合法系统启动——密钥轮换、恢复模式、AB 双库是这条链的运维面。下一课固件。可以把它想象成环环相扣的公证：<span class="marginnote">直觉类比：最底层的公证员（ROM）物理上收买不了，之后每一级公证员只给「上一级盖过章的文件」再盖章——任何一环拒绝盖章，后面的文件就全部作废，这就是为什么链的强度等于最弱一环。</span></p>',11)),(t(),n(i,null,{default:e(()=>[l(r,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20ROM%5B%22ROM%20%E9%94%9A%22%5D%20--%3E%20FW%5B%22%E5%9B%BA%E4%BB%B6%22%5D%0A%20%20FW%20--%3E%20LDR%5B%22%E5%BC%95%E5%AF%BC%E5%99%A8%22%5D%0A%20%20LDR%20--%3E%20OS%5B%22%E5%86%85%E6%A0%B8%22%5D%0A%20%20FW%20--%3E%20SIG%5B%22%E6%AF%8F%E7%BA%A7%E9%AA%8C%E7%AD%BE%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[o(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("h2",{id:"机制",tabindex:"-1"},[o("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=E("p",null,"机制上，启动完整是后续一切的前提：内核的 MAC、TEE 的度量、远程证明的 PCR 值，全都假设「起点诚实」——固件被改则链从根上烂，上层做得再对也是假地基。安全启动的投入因此集中在「锚」：ROM 与根密钥不可变、不可调试——整台机器最贵的几平方毫米。下一课固件安全讲更新与植入。",-1)),a[5]||(a[5]=E("p",null,"固件对单个镜像的放行判定，本质是一次「先查黑名单、再查白名单」的两次查询：",-1)),(t(),n(i,null,{default:e(()=>[l(r,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20IMG%5B%22%E5%BE%85%E5%90%AF%E5%8A%A8%E9%95%9C%E5%83%8F%E5%B0%B1%E4%BD%8D%22%5D%20--%3E%20X%7B%22%E5%85%B6%E5%93%88%E5%B8%8C%E6%88%96%E7%AD%BE%E5%90%8D%E5%9C%A8%20dbx%20%E5%90%8A%E9%94%80%E5%BA%93%3F%22%7D%0A%20%20X%20--%20%22%E5%9C%A8%22%20--%3E%20REJ%5B%22%E6%8B%92%E7%BB%9D%E6%89%A7%E8%A1%8C%22%5D%0A%20%20X%20--%20%22%E4%B8%8D%E5%9C%A8%22%20--%3E%20D%7B%22%E8%83%BD%E8%A2%AB%20db%20%E4%B8%AD%E7%9A%84%E5%AF%86%E9%92%A5%E6%9C%89%E6%95%88%E7%AD%BE%E5%90%8D%3F%22%7D%0A%20%20D%20--%20%22%E6%98%AF%22%20--%3E%20RUN%5B%22%E6%94%BE%E8%A1%8C%2C%20%E8%BF%9B%E5%85%A5%E4%B8%8B%E4%B8%80%E7%BA%A7%22%5D%0A%20%20D%20--%20%22%E5%90%A6%22%20--%3E%20REJ%0A%20%20KEK%5B%22KEK%20%E7%BB%B4%E6%8A%A4%20db%20%E4%B8%8E%20dbx%22%5D%20-.%20%E6%8E%88%E6%9D%83%E5%A2%9E%E5%88%A0%20.-%3E%20D%0A%20%20PK%5B%22%E5%B9%B3%E5%8F%B0%E6%89%80%E6%9C%89%E8%80%85%20PK%22%5D%20-.%20%E7%AD%BE%E5%8F%91%20KEK%20.-%3E%20KEK%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[o(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=s('<p><span class="marginnote">常见误区：初学者容易把「镜像通过验签」读成「镜像没有漏洞」——签名链只回答「谁签的、签完有没有被改」，签过名的固件照样可能带着已知的洞被利用，所以签名链必须配漏洞响应与 dbx 吊销流程才闭环。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不写关闭验证的步骤；边界要点名：安全启动验证的是「谁签的」，不是「没有洞」——签过的固件带洞照样可被利用，签名链必须配漏洞响应流程。固件安全下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>证明假设启动度量诚实；安全启动守本地链。</li><li>ROM 锚到内核逐级验签。</li><li>更新与密钥是运营 TCB。</li><li>下一课固件安全。</li><li>出处：UEFI Secure Boot；NIST SP 800-147；Anderson。</li></ul>',5))])}const _=d(p,[["render",b]]);export{C as __pageData,_ as default};
